# Rule 4: Safety
# -------------------------


def _bp(sbp: float, dbp: float, at: datetime, has_time: bool = True) -> Vital:
    return Vital("BP", at, has_time, "text", EvidenceItem(source="document", value=f"{sbp}/{dbp}"),
                 systolic=sbp, diastolic=dbp)


